input.contents:
/**
 * Web 用户端桥接：历史、附件、引用原文、反馈闭环、运营指标
 * 仅 web端/index.html 加载
 */
(function (global) {
  var HISTORY_KEY = 'proto_user_chat_history';
  var EVENTS_KEY = 'platform_api_portal_events';
  var HISTORY_PAGE_SIZE = 15;
  var HISTORY_MAX = 100;

  var sourceState = 'failed';
  var attachState = null;
  var historyVisibleCount = HISTORY_PAGE_SIZE;
  var historySearchQuery = '';

  function readHistory() {
    try {
      var raw = sessionStorage.getItem(HISTORY_KEY);
      if (raw) return JSON.parse(raw);
    } catch (e) {}
    return [];
  }

  function writeHistory(list) {
    try { sessionStorage.setItem(HISTORY_KEY, JSON.stringify(list)); } catch (e) {}
  }

  function trackEvent(name, payload) {
    var list = [];
    try {
      var raw = sessionStorage.getItem(EVENTS_KEY);
      if (raw) list = JSON.parse(raw);
    } catch (e) {}
    list.push({
      event: name,
      at: new Date().toISOString(),
      payload: payload || {}
    });
    if (list.length > 300) list = list.slice(-300);
    try { sessionStorage.setItem(EVENTS_KEY, JSON.stringify(list)); } catch (e2) {}
    if (global.PlatformApi && PlatformApi.bumpMetrics && payload && payload.agent_id) {
      PlatformApi.bumpMetrics(payload.agent_id, { calls: 0 });
    }
  }

  function toast(msg) {
    if (global.Proto && Proto.toast) Proto.toast(msg);
  }

  function saveHistoryEntry(agent, model, preview) {
    var list = readHistory();
    var entry = {
      id: 'hist_' + Date.now().toString(36),
      agentId: agent.id,
      agentName: agent.name,
      model: model,
      title: (preview || '').slice(0, 40) || '新对话',
      preview: (preview || '').slice(0, 80),
      updatedAt: new Date().toISOString()
    };
    list = [entry].concat(list.filter(function (x) {
      return !(x.agentId === entry.agentId && x.title === entry.title);
    })).slice(0, HISTORY_MAX);
    writeHistory(list);
    renderHistoryModal();
  }

  function escapeHtml(value) {
    return String(value == null ? '' : value).replace(/[&<>"']/g, function (ch) {
      return ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[ch];
    });
  }

  function historyGroupLabel(iso) {
    var d = new Date(iso);
    if (isNaN(d.getTime())) return '更早';
    var now = new Date();
    var startToday = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    var startYesterday = new Date(startToday);
    startYesterday.setDate(startYesterday.getDate() - 1);
    var startWeek = new Date(startToday);
    startWeek.setDate(startWeek.getDate() - 7);
    if (d >= startToday) return '今天';
    if (d >= startYesterday) return '昨天';
    if (d >= startWeek) return '近 7 天';
    return '更早';
  }

  function filterHistory(list) {
    var q = historySearchQuery.trim().toLowerCase();
    if (!q) return list;
    return list.filter(function (item) {
      return [item.title, item.preview, item.agentName, item.model].join(' ').toLowerCase().indexOf(q) >= 0;
    });
  }

  function renderHistoryModal() {
    var modal = document.getElementById('historyModal');
    var listEl = document.getElementById('historyList');
    var loadMore = document.getElementById('btnHistoryLoadMore');
    if (!listEl) return;

    var all = filterHistory(readHistory());
    var visible = all.slice(0, historyVisibleCount);
    if (!visible.length) {
      listEl.innerHTML = '<p class="aioq-muted">暂无历史记录</p>';
      if (loadMore) loadMore.classList.add('hidden');
      return;
    }

    var groups = {};
    visible.forEach(function (item) {
      var label = historyGroupLabel(item.updatedAt);
      if (!groups[label]) groups[label] = [];
      groups[label].push(item);
    });

    var order = ['今天', '昨天', '近 7 天', '更早'];
    var html = '';
    order.forEach(function (label) {
      if (!groups[label] || !groups[label].length) return;
      html += '<div class="aioq-history-group-title">' + label + '</div>';
      html += '<div class="aioq-history-list">';
      html += groups[label].map(function (item) {
        return '<button type="button" class="aioq-history-item" data-history-id="' + item.id + '">' +
          '<strong>' + escapeHtml(item.title) + '</strong>' +
          '<span>' + escapeHtml(item.agentName) + ' · ' + escapeHtml(item.model) + '</span>' +
          '<small>' + escapeHtml(item.preview) + '</small>' +
        '</button>';
      }).join('');
      html += '</div>';
    });
    listEl.innerHTML = html;

    if (loadMore) {
      if (all.length > historyVisibleCount) {
        loadMore.classList.remove('hidden');
        loadMore.textContent = '加载更多（' + (all.length - historyVisibleCount) + ' 条）';
      } else {
        loadMore.classList.add('hidden');
      }
    }
  }

  function openHistoryModal() {
    var modal = document.getElementById('historyModal');
    if (!modal) return;
    historyVisibleCount = HISTORY_PAGE_SIZE;
    historySearchQuery = '';
    var search = document.getElementById('historySearchInput');
    if (search) search.value = '';
    renderHistoryModal();
    modal.classList.remove('hidden');
  }

  function closeHistoryModal() {
    var modal = document.getElementById('historyModal');
    if (modal) modal.classList.add('hidden');
  }

  function renderAttachChip() {
    var chip = document.getElementById('attachChip');
    if (!chip) return;
    if (!attachState) {
      chip.classList.add('hidden');
      chip.innerHTML = '';
      return;
    }
    chip.classList.remove('hidden');
    var statusText = attachState.status === 'uploading' ? '上传中…'
      : attachState.status === 'failed' ? '上传失败'
      : '已附加';
    chip.innerHTML =
      '<span class="aioq-attach-chip">' + escapeHtml(attachState.name) + ' · ' + statusText +
      (attachState.status === 'failed' ? ' <button type="button" id="btnRetryAttach">重试</button>' : '') +
      ' <button type="button" id="btnRemoveAttach">×</button></span>';
    var retry = document.getElementById('btnRetryAttach');
    var remove = document.getElementById('btnRemoveAttach');
    if (retry) retry.onclick = function () { simulateUpload(attachState.file); };
    if (remove) remove.onclick = function () { attachState = null; renderAttachChip(); };
  }

  function simulateUpload(file) {
    if (!file) return;
    attachState = { name: file.name, file: file, status: 'uploading' };
    renderAttachChip();
    setTimeout(function () {
      attachState = attachState ? Object.assign({}, attachState, { status: Math.random() > 0.15 ? 'done' : 'failed' }) : null;
      renderAttachChip();
      if (attachState && attachState.status === 'done') toast('附件已就绪');
      if (attachState && attachState.status === 'failed') toast('附件上传失败，请重试');
    }, 900);
  }

  function renderSourcePanel(mode) {
    var body = document.getElementById('sourcePanelBody');
    var empty = document.querySelector('.aioq-source-empty');
    if (!body) return;
    if (sourceState === 'loading') {
      body.innerHTML = '<div class="aioq-source-loading">原文加载中…</div>';
      if (empty) empty.classList.add('hidden');
      return;
    }
    if (sourceState === 'failed') {
      body.innerHTML = '';
      if (empty) empty.classList.remove('hidden');
      return;
    }
    if (empty) empty.classList.add('hidden');
    if (mode === 'excerpt') {
      body.innerHTML = '<ol class="aioq-source-excerpts"><li>引用段落 1：制度条款与现场要求一致。</li><li>引用段落 2：风险分级需结合井况复核。</li></ol>';
    } else {
      body.innerHTML = '<div class="aioq-source-doc"><p>原文预览（演示）：企业知识库文档全文占位。</p></div>';
    }
  }

  function loadSourceDocument() {
    sourceState = 'loading';
    renderSourcePanel('doc');
    setTimeout(function () {
      sourceState = Math.random() > 0.1 ? 'ready' : 'failed';
      renderSourcePanel('doc');
    }, 700);
  }

  function collectFeedbackPayload() {
    var reasons = [];
    document.querySelectorAll('#feedbackReasons input:checked').forEach(function (input) {
      reasons.push(input.value);
    });
    var text = (document.getElementById('feedbackText') || {}).value || '';
    var agent = UserChatPortal.activeAgent();
    return { reasons: reasons, text: text, agent: agent.name, agentId: agent.id };
  }

  function submitFeedbackFromModal() {
    var payload = collectFeedbackPayload();
    if (!payload.reasons.length && !payload.text.trim()) {
      toast('请选择反馈类型或填写说明');
      return;
    }
    if (global.UserMessageCenter && UserMessageCenter.pushFeedbackFromChat) {
      UserMessageCenter.pushFeedbackFromChat(payload);
    }
    var fbId = global.OpsUserFeedback && OpsUserFeedback.createFromChat
      ? OpsUserFeedback.createFromChat(payload)
      : null;
    if (fbId && global.OpsFeedbackLoop && OpsFeedbackLoop.createTaskFromFeedback) {
      OpsFeedbackLoop.createTaskFromFeedback(fbId);
    }
    trackEvent('feedback_submit', {
      agent_id: payload.agentId,
      feedback_id: fbId,
      reasons: payload.reasons
    });
    toast('反馈已提交');
    document.getElementById('chatFeedbackModal').classList.add('hidden');
    document.querySelectorAll('#feedbackReasons input').forEach(function (i) { i.checked = false; });
    var ft = document.getElementById('feedbackText');
    if (ft) ft.value = '';
  }

  function requestExpert() {
    var agent = UserChatPortal.activeAgent();
    var st = UserChatPortal.getState();
    var payload = collectFeedbackPayload();
    payload.reasons = ['生成内容错误'];
    payload.text = payload.text || '用户请求专家复核当前回答';
    var fbId = global.OpsUserFeedback && OpsUserFeedback.createFromChat
      ? OpsUserFeedback.createFromChat(payload)
      : null;
    if (fbId && global.OpsFeedbackLoop && OpsFeedbackLoop.createTaskFromFeedback) {
      OpsFeedbackLoop.createTaskFromFeedback(fbId);
    }
    trackEvent('expert_request', { agent_id: agent.id, model_tier: st.model, feedback_id: fbId });
    toast('已提交专家复核请求');
  }

  function bindUi() {
    var btnHistory = document.getElementById('btnHistory');
    var historyModal = document.getElementById('historyModal');
    var btnCloseHistory = document.getElementById('btnCloseHistory');
    if (btnHistory) {
      btnHistory.addEventListener('click', openHistoryModal);
    }
    if (historyModal) {
      historyModal.addEventListener('click', function (e) {
        if (e.target.id === 'historyModal') closeHistoryModal();
      });
      var box = historyModal.querySelector('.modal-box');
      if (box) box.addEventListener('click', function (e) { e.stopPropagation(); });
    }
    if (btnCloseHistory) {
      btnCloseHistory.addEventListener('click', closeHistoryModal);
    }
    var historySearch = document.getElementById('historySearchInput');
    if (historySearch) {
      historySearch.addEventListener('input', function () {
        historySearchQuery = historySearch.value || '';
        historyVisibleCount = HISTORY_PAGE_SIZE;
        renderHistoryModal();
      });
    }
    var btnLoadMore = document.getElementById('btnHistoryLoadMore');
    if (btnLoadMore) {
      btnLoadMore.addEventListener('click', function () {
        historyVisibleCount += HISTORY_PAGE_SIZE;
        renderHistoryModal();
      });
    }
    var historyList = document.getElementById('historyList');
    if (historyList) {
      historyList.addEventListener('click', function (e) {
        var btn = e.target.closest('[data-history-id]');
        if (!btn) return;
        var item = readHistory().find(function (x) { return x.id === btn.getAttribute('data-history-id'); });
        if (!item) return;
        UserChatPortal.selectAgent(item.agentId);
        var st = UserChatPortal.getState();
        st.model = item.model;
        toast('已恢复历史会话：' + item.title);
        closeHistoryModal();
      });
    }

    var btnAttach = document.getElementById('btnAttach');
    var fileInput = document.getElementById('chatFileInput');
    if (btnAttach && fileInput) {
      btnAttach.addEventListener('click', function () { fileInput.click(); });
      fileInput.addEventListener('change', function () {
        if (fileInput.files && fileInput.files[0]) simulateUpload(fileInput.files[0]);
        fileInput.value = '';
      });
    }

    var btnSourceDownload = document.getElementById('btnSourceDownload');
    if (btnSourceDownload) {
      btnSourceDownload.addEventListener('click', function () {
        if (sourceState !== 'ready') return;
        var agent = UserChatPortal.activeAgent();
        trackEvent('file_download', { agent_id: agent.id, kind: 'source_doc' });
        toast('原文下载已开始（演示）');
      });
    }

    sourceState = 'failed';
    renderSourcePanel('excerpt');
  }

  function init(sessionSkills) {
    var ctx = UserPortalContext.get();
    var grouped = UserAgentResolver.resolve(ctx);
    var all = grouped.personal.concat(grouped.org, grouped.enterprise);
    if (!all.length) grouped.enterprise = UserChatPortal.getDefaultAgents().slice(0, 3);

    UserChatPortal.init({
      mode: 'web',
      groupedAgents: grouped,
      sessionSkills: sessionSkills,
      onChatStart: function (info) {
        trackEvent('chat_start', {
          agent_id: info.agent.id,
          model_tier: info.model,
          skills_hit: info.skillIds || []
        });
      },
      onChatComplete: function (info) {
        saveHistoryEntry(info.agent, info.model, info.text);
      },
      onViewSource: function () {
        var panel = document.getElementById('sourcePanel');
        if (panel) panel.classList.remove('hidden');
        loadSourceDocument();
      },
      onCiteExcerpt: function () {
        sourceState = 'ready';
        renderSourcePanel('excerpt');
      }
    });

    var btnSubmitFeedback = document.getElementById('btnSubmitFeedback');
    var btnCancelFeedback = document.getElementById('btnCancelFeedback');
    var btnCloseFeedback = document.getElementById('btnCloseFeedback');
    if (btnSubmitFeedback) btnSubmitFeedback.addEventListener('click', submitFeedbackFromModal);
    if (btnCancelFeedback) btnCancelFeedback.addEventListener('click', function () {
      document.getElementById('chatFeedbackModal').classList.add('hidden');
    });
    if (btnCloseFeedback) btnCloseFeedback.addEventListener('click', function () {
      document.getElementById('chatFeedbackModal').classList.add('hidden');
    });

    bindUi();
    renderHistoryModal();

    if (global.location && global.location.hash === '#history') {
      openHistoryModal();
    }
  }

  global.UserPortalBridge = {
    init: init,
    openHistory: openHistoryModal,
    closeHistory: closeHistoryModal,
    trackEvent: trackEvent
  };
})(window);

